/* Record Room service worker - generated by samples/tools/build-site.js */
const VERSION='107f02823228';
const CACHE='record-room-'+VERSION;
const SHELL=['/','/index.html','/manifest.webmanifest',
  '/icon-192.png','/icon-512.png','/apple-touch-icon.png',
  '/vendor/lenis.min.js','/vendor/smooth.js','/vendor/ambient.js'];
/* three.module.min.js is 670KB and only some visitors ever load it, so it is
   left out of the precache and picked up by the runtime cache on first use. */

self.addEventListener('install',e=>{
  e.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL)).then(()=>self.skipWaiting()));
});
self.addEventListener('activate',e=>{
  e.waitUntil(caches.keys()
    .then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k))))
    .then(()=>self.clients.claim()));
});
self.addEventListener('fetch',e=>{
  const req=e.request;
  if(req.method!=='GET')return;
  const url=new URL(req.url);
  if(url.origin!==location.origin)return;        // Sleeper always goes to the network

  if(req.mode==='navigate'){                      // newest page wins, cache is the fallback
    e.respondWith(fetch(req).then(res=>{
      const copy=res.clone();
      caches.open(CACHE).then(c=>c.put('/index.html',copy));
      return res;
    }).catch(()=>caches.match('/index.html').then(r=>r||caches.match('/'))));
    return;
  }
  e.respondWith(caches.match(req).then(hit=>{
    const net=fetch(req).then(res=>{
      if(res&&res.status===200){const copy=res.clone();caches.open(CACHE).then(c=>c.put(req,copy));}
      return res;
    }).catch(()=>hit);
    return hit||net;
  }));
});
